-- Digital Fees Register — demo seed for ALL 13 classes (Nursery → 10).
-- ----------------------------------------------------------------------------
-- Purpose: populate the DEMO Supabase project (fees-register-v1) with
-- synthetic data so every class register shows realistic content and the
-- Today/MTD tiles light up against the page's dynamic "today" (Asia/Kolkata).
--
-- Guardrails (CLAUDE.md):
--   · Every name, parent name, phone, address, DOB, Aadhaar, PEN below is
--     INVENTED. No real students, families, or schools.
--   · Class identifiers match the canonical CLASS_LIST in lib/classes.ts
--     exactly — "Nursery" / "LKG" / "UKG" / "1" … "10".
--
-- Idempotent: wraps everything in a transaction, TRUNCATEs the four data
-- tables, leaves `settings` (and the auth user) untouched.
--
-- Cross-class sibling groups (drive sibling chip + chip-jump demos):
--   · F2  VERMA   — Class 10 + Class 8
--   · F4  KUMAR   — Class 10 + Class 7 + Class 5
--   · F6  GUPTA   — Class 10 + Class 9
--   · F7  JOSHI   — Class 10 + Class 5
--   · F10 IYER    — Class 3  + Class 6        (added for the demo)
--   · F11 NAIR    — Class UKG + Class 4 + Class 8 (added for the demo)
--
-- Per-class headcount:
--   · Class 10: 9 students (the existing seed shape, unchanged names)
--   · All other classes: 5 students each
--   Total: 12 × 5 + 9 = 69 students across 61 families.
--
-- Fee structures: one row per canonical class, ALL at Class-10 values
-- (₹1500 monthly · ₹1500 annual · ₹400 Sep + Feb exam · ₹0 misc → ₹20,300/yr).
--
-- Payment dates: school-session months ('2026-04' / '2026-05' / '2026-06')
-- with paid_on values chosen RELATIVE to the Asia/Kolkata current date so the
-- Today tile + MTD tile both render non-zero on a fresh run. Static Apr/May
-- dates remain (already-past session months); current-month payments come
-- from a DO block that reads (current_timestamp at time zone 'Asia/Kolkata').
-- ----------------------------------------------------------------------------

begin;

truncate table payments, students, families, fee_structures restart identity cascade;

-- ----------------------------------------------------------------------------
-- fee_structures — real fee ladder from the Principal's letter:
--   Nursery/LKG/UKG  → annual 1200 · monthly 1100 · exam 100
--   Classes 1-5      → annual 1500 · monthly 1200 · exam 200
--   Classes 6-8      → annual 1500 · monthly 1300 · exam 300
--   Classes 9-10     → annual 1500 · monthly 1500 · exam 400
-- "Exam fee" applies to BOTH the Sep + Feb terms. Class 10 sanity:
--   1500 × 12 + 1500 + 400 + 400 = 20,300 / yr.
-- ----------------------------------------------------------------------------
insert into fee_structures
  (class, monthly_fee, annual_fee, sep_exam_fee, feb_exam_fee, misc_fee, effective_from)
values
  ('Nursery', 1100, 1200, 100, 100, 0, '2026-04-01'),
  ('LKG',     1100, 1200, 100, 100, 0, '2026-04-01'),
  ('UKG',     1100, 1200, 100, 100, 0, '2026-04-01'),
  ('1',       1200, 1500, 200, 200, 0, '2026-04-01'),
  ('2',       1200, 1500, 200, 200, 0, '2026-04-01'),
  ('3',       1200, 1500, 200, 200, 0, '2026-04-01'),
  ('4',       1200, 1500, 200, 200, 0, '2026-04-01'),
  ('5',       1200, 1500, 200, 200, 0, '2026-04-01'),
  ('6',       1300, 1500, 300, 300, 0, '2026-04-01'),
  ('7',       1300, 1500, 300, 300, 0, '2026-04-01'),
  ('8',       1300, 1500, 300, 300, 0, '2026-04-01'),
  ('9',       1500, 1500, 400, 400, 0, '2026-04-01'),
  ('10',      1500, 1500, 400, 400, 0, '2026-04-01');

