-- ----------------------------------------------------------------------------
-- payments — RELATIVE-DATE rows. Asia/Kolkata "today" computed once so the
-- Today / MTD tiles light up on a fresh run regardless of the server clock.
-- Distributes a small number of CURRENT_DATE payments + a few CURRENT_DATE-N
-- payments across classes, so every class register has SOME current-month
-- activity. Periods always use the canonical Monthly = YYYY-MM (the
-- current-month period derived from today_ist).
-- ----------------------------------------------------------------------------
do $$
declare
  today_ist date := (current_timestamp at time zone 'Asia/Kolkata')::date;
  cur_period text := to_char(today_ist, 'YYYY-MM');
begin
  -- Class 10 — replace the original 2026-05-26 rows with today-relative ones.
  -- AARAV (F1, Class 10 — monthly 1500) — Monthly current-period paid today
  insert into payments (family_id, student_id, fee_head, period, amount, paid_on, payment_mode, reference_no, notes) values
    ('11111111-1111-1111-1111-000000000001', '22222222-2222-2222-2222-000000000001', 'Monthly', cur_period, 1500, today_ist,        'UPI',  'UPI'||to_char(today_ist,'YYMMDD')||'AS1', null),
    -- MYRA (F5, Class 10 — monthly 1500) — paid today
    ('11111111-1111-1111-1111-000000000005', '22222222-2222-2222-2222-000000000005', 'Monthly', cur_period, 1500, today_ist,        'Cash', null, null),
    -- KAVYA VERMA (Class 8 — monthly 1300) — paid 2 days ago
    ('11111111-1111-1111-1111-000000000002', '22222222-2222-2222-2222-000000000011', 'Monthly', cur_period, 1300, today_ist - 2,    'UPI',  'UPI'||to_char(today_ist - 2,'YYMMDD')||'VR2', null),
    -- AANYA KUMAR (Class 5 — monthly 1200) — paid 1 day ago
    ('11111111-1111-1111-1111-000000000004', '22222222-2222-2222-2222-000000000018', 'Monthly', cur_period, 1200, today_ist - 1,    'Cash', null, null),
    -- PARAM GUPTA (Class 9 — monthly 1500) — paid today
    ('11111111-1111-1111-1111-000000000006', '22222222-2222-2222-2222-000000000015', 'Monthly', cur_period, 1500, today_ist,        'UPI',  'UPI'||to_char(today_ist,'YYMMDD')||'GP1', null),
    -- ANANYA IYER (Class 3 — monthly 1200) — paid today
    ('11111111-1111-1111-1111-000000000010', '22222222-2222-2222-2222-000000000020', 'Monthly', cur_period, 1200, today_ist,        'Cash', null, null),
    -- DEV NAIR (UKG — monthly 1100) — paid today
