-- ----------------------------------------------------------------------------
-- Per-class summary so the run-sql.mjs runner prints something useful.
-- ----------------------------------------------------------------------------
select
  s.class                                  as class,
  count(distinct s.id)::int                as students,
  count(distinct s.family_id)::int         as families,
  count(distinct p.id)::int                as payments
from students s
left join payments p
  on p.status = 'active'
 and (p.student_id = s.id or (p.student_id is null and p.family_id = s.family_id))
group by s.class
order by
  case s.class
    when 'Nursery' then 0 when 'LKG' then 1 when 'UKG' then 2
    else 2 + s.class::int
  end;

commit;
